select throws_ok($$select public.prepare_payment_delivery((select id from fx where k='delivery'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'EMAIL','payment@example.test','Invoice','Missing link')$$,'23514',null,'Message requires exactly one payment placeholder');
select throws_ok($$select public.prepare_payment_delivery((select id from fx where k='delivery'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'SMS','+13035550404','','Pay: {{payment_link}}')$$,'42501',null,'SMS without current consent denied');
select throws_ok($$select public.prepare_payment_delivery((select id from fx where k='second'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'EMAIL','payment@example.test','Invoice','Pay: {{payment_link}} {{payment_link}}')$$,'23514',null,'Duplicate capability placeholders rejected');
select throws_ok($$select public.prepare_payment_delivery((select id from fx where k='second'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'EMAIL','payment@example.test','Invoice','Pay: {{payment_link}} p1.'||repeat('a',43))$$,'23514',null,'Usable capability rejected at delivery persistence boundary');
select lives_ok($$select public.prepare_payment_delivery((select id from fx where k='delivery'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'EMAIL','payment@example.test','Invoice','Pay: {{payment_link}}')$$,'Prepare distinct immutable delivery');
select lives_ok($$select public.prepare_payment_delivery((select id from fx where k='delivery'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'EMAIL','payment@example.test','Invoice','Pay: {{payment_link}}')$$,'Prepare exact retry recovers');
select throws_ok($$select public.prepare_payment_delivery((select id from fx where k='delivery'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'EMAIL','payment@example.test','Changed','Pay: {{payment_link}}')$$,'23505',null,'UUID cannot change reviewed intent');
select throws_ok($$select public.capture_payment_delivery((select id from fx where k='delivery'),auth.uid(),'{"from":"billing@thelivingroom.vet","reply_to":"billing@thelivingroom.vet"}',repeat('c',64),repeat('d',64))$$,'42501',null,'Staff cannot fabricate service digest');
