select ok((public.start_communication_attempt((select id from fx where k='attached-outbox'),'73700000-0000-4000-8000-000000000090',jsonb_build_object('from','billing@thelivingroom.vet','reply_to','billing@thelivingroom.vet','payment_delivery_message_hash',repeat('e',64),'payment_delivery_payload_hash',repeat('f',64)))).attempt_started_at is not null,'Exact sender and materialization proof opens guarded attempt');
