select lives_ok($$select public.enqueue_payment_delivery((select id from fx where k='delivery'),repeat('c',64),repeat('d',64),true)$$,'Committed receipt recovers before grant eligibility after revocation');
select is(public.recover_payment_delivery((select id from fx where k='delivery'))#>>'{receipt,state}','failed','Recovery reports actual receipt state');
select throws_ok($$select public.prepare_payment_delivery((select id from fx where k='second'),(select id from fx where k='grant'),(select id from fx where k='conversation'),'EMAIL','payment@example.test','Invoice','Pay: {{payment_link}}')$$,'42501',null,'Revocation prevents new delivery');
select set_config('request.jwt.claims','{"sub":"73700000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.recover_payment_delivery((select id from fx where k='delivery')),null::jsonb,'Other actor cannot recover delivery');
reset role;
select throws_ok($$delete from public.payment_delivery_captures$$,'23514',null,'Digest evidence append only');
set local role anon;
select throws_ok($$select * from public.payment_delivery_requests$$,'42501',null,'Anonymous direct access denied');
select * from finish();
rollback;
